    <script>
        // CHIP-8 Emulator Implementation
        class CHIP8 {
            constructor() {
                // Memory: 4KB (4096 bytes)
                this.memory = new Uint8Array(4096);

                // Registers
                this.v = new Uint8Array(16); // V0-VF
                this.i = 0; // Index register

                // Timers
                this.delayTimer = 0;
                this.soundTimer = 0;

                // Program counter
                this.pc = 0x200; // Programs start at 0x200

                // Stack
                this.stack = new Uint16Array(16);
                this.sp = 0; // Stack pointer

                // Display
                this.display = new Uint8Array(64 * 32); // 64x32 pixels

                // Key state
                this.keys = new Uint8Array(16);

                // Instruction set
                this.instructions = {
                    0x0000: this._0xxx.bind(this),
                    0x1000: this._1xxx.bind(this),
                    0x2000: this._2xxx.bind(this),
                    0x3000: this._3xxx.bind(this),
                    0x4000: this._4xxx.bind(this),
                    0x5000: this._5xxx.bind(this),
                    0x6000: this._6xxx.bind(this),
                    0x7000: this._7xxx.bind(this),
                    0x8000: this._8xxx.bind(this),
                    0x9000: this._9xxx.bind(this),
                    0xA000: this._Axxx.bind(this),
                    0xB000: this._Bxxx.bind(this),
                    0xC000: this._Cxxx.bind(this),
                    0xD000: this._Dxxx.bind(this),
                    0xE000: this._Exxx.bind(this),
                    0xF000: this._Fxxx.bind(this)
                };

                // Font set (5 bytes per digit)
                this.fontSet = [
                    0xF0, 0x90, 0x90, 0x90, 0xF0, // 0
                    0x20, 0x60, 0x20, 0x20, 0x70, // 1
                    0xF0, 0x10, 0xF0, 0x80, 0xF0, // 2
                    0xF0, 0x10, 0xF0, 0x10, 0xF0, // 3
                    0x90, 0x90, 0xF0, 0x10, 0x10, // 4
                    0xF0, 0x80, 0xF0, 0x10, 0xF0, // 5
                    0xF0, 0x80, 0xF0, 0x90, 0xF0, // 6
                    0xF0, 0x10, 0x20, 0x40, 0x40, // 7
                    0xF0, 0x90, 0xF0, 0x90, 0xF0, // 8
                    0xF0, 0x90, 0xF0, 0x10, 0xF0, // 9
                    0xF0, 0x90, 0xF0, 0x90, 0x90, // A
                    0xE0, 0x90, 0xE0, 0x90, 0xE0, // B
                    0xF0, 0x80, 0x80, 0x80, 0xF0, // C
                    0xE0, 0x90, 0x90, 0x90, 0xE0, // D
                    0xF0, 0x80, 0xF0, 0x80, 0xF0, // E
                    0xF0, 0x80, 0xF0, 0x80, 0x80  // F
                ];

                // Load font set into memory at 0x050
                for (let i = 0; i < this.fontSet.length; i++) {
                    this.memory[0x050 + i] = this.fontSet[i];
                }

                // Current instruction
                this.currentInstruction = 0;

                // Execution state
                this.running = false;
                this.paused = false;
                this.stepping = false;

                // Timer handling
                this.timerInterval = null;
                this.executionInterval = null;

                // Initialize
                this.reset();
            }

            reset() {
                // Clear memory (except font set)
                for (let i = 0; i < 4096; i++) {
                    if (i < 0x050 || i >= 0x050 + this.fontSet.length) {
                        this.memory[i] = 0;
                    }
                }

                // Clear registers
                this.v.fill(0);
                this.i = 0;
                this.pc = 0x200;
                this.sp = 0;
                this.delayTimer = 0;
                this.soundTimer = 0;

                // Clear display
                this.display.fill(0);

                // Clear keys
                this.keys.fill(0);

                // Reset execution state
                this.running = false;
                this.paused = false;
                this.stepping = false;

                // Clear instruction
                this.currentInstruction = 0;

                // Update display
                this.updateDisplay();
                this.updateDebugger();
            }

            loadROM(romData) {
                // Load ROM at 0x200
                for (let i = 0; i < romData.length; i++) {
                    if (0x200 + i < 4096) {
                        this.memory[0x200 + i] = romData[i];
                    }
                }

                // Reset and start execution
                this.reset();
                this.pc = 0x200;
                this.updateDebugger();

                // Show status
                document.getElementById('status').textContent = 'ROM loaded successfully';
            }

            updateDisplay() {
                const canvas = document.getElementById('display');
                const ctx = canvas.getContext('2d');
                const imageData = ctx.createImageData(64, 32);

                for (let i = 0; i < 64 * 32; i++) {
                    const pixel = this.display[i];
                    const idx = i * 4;
                    if (pixel === 1) {
                        imageData.data[idx] = 255;     // R
                        imageData.data[idx + 1] = 255; // G
                        imageData.data[idx + 2] = 255; // B
                        imageData.data[idx + 3] = 255; // A
                    } else {
                        imageData.data[idx] = 0;       // R
                        imageData.data[idx + 1] = 0;   // G
                        imageData.data[idx + 2] = 0;   // B
                        imageData.data[idx + 3] = 255; // A
                    }
                }

                ctx.putImageData(imageData, 0, 0);
            }

            updateDebugger() {
                document.getElementById('pc').textContent = '0x' + this.pc.toString(16).padStart(3, '0');
                document.getElementById('i').textContent = '0x' + this.i.toString(16).padStart(3, '0');
                document.getElementById('dt').textContent = this.delayTimer;
                document.getElementById('st').textContent = this.soundTimer;

                // Stack
                const stackStr = [];
                for (let i = 0; i < this.sp; i++) {
                    stackStr.push('0x' + this.stack[i].toString(16).padStart(3, '0'));
                }
                document.getElementById('stack').textContent = '[' + stackStr.join(', ') + ']';

                // V registers
                for (let i = 0; i < 16; i++) {
                    document.getElementById('v' + i.toString(16).toUpperCase()).textContent = '0x' + this.v[i].toString(16).padStart(2, '0');
                }

                // Current instruction
                const hex = this.currentInstruction.toString(16).padStart(4, '0');
                const decoded = this.decodeInstruction(this.currentInstruction);
                document.getElementById('currentInstruction').textContent = '0x' + hex + ' (' + decoded + ')';
            }

            decodeInstruction(opcode) {
                const x = (opcode & 0x0F00) >> 8;
                const y = (opcode & 0x00F0) >> 4;
                const n = opcode & 0x000F;
                const nn = opcode & 0x00FF;
                const nnn = opcode & 0x0FFF;

                switch (opcode & 0xF000) {
                    case 0x0000:
                        if (opcode === 0x00E0) return 'CLS';
                        if (opcode === 0x00EE) return 'RET';
                        return 'SYS ' + nnn.toString(16).toUpperCase();
                    case 0x1000: return 'JP ' + nnn.toString(16).toUpperCase();
                    case 0x2000: return 'CALL ' + nnn.toString(16).toUpperCase();
                    case 0x3000: return 'SE V' + x + ', ' + nn.toString(16).toUpperCase();
                    case 0x4000: return 'SNE V' + x + ', ' + nn.toString(16).toUpperCase();
                    case 0x5000: return 'SE V' + x + ', V' + y;
                    case 0x6000: return 'LD V' + x + ', ' + nn.toString(16).toUpperCase();
                    case 0x7000: return 'ADD V' + x + ', ' + nn.toString(16).toUpperCase();
                    case 0x8000:
                        switch (n) {
                            case 0x0: return 'LD V' + x + ', V' + y;
                            case 0x1: return 'OR V' + x + ', V' + y;
                            case 0x2: return 'AND V' + x + ', V' + y;
                            case 0x3: return 'XOR V' + x + ', V' + y;
                            case 0x4: return 'ADD V' + x + ', V' + y;
                            case 0x5: return 'SUB V' + x + ', V' + y;
                            case 0x6: return 'SHR V' + x + ', V' + y;
                            case 0x7: return 'SUBN V' + x + ', V' + y;
                            case 0xE: return 'SHL V' + x + ', V' + y;
                            default: return 'UNKNOWN';
                        }
                    case 0x9000: return 'SNE V' + x + ', V' + y;
                    case 0xA000: return 'LD I, ' + nnn.toString(16).toUpperCase();
                    case 0xB000: return 'JP V0, ' + nnn.toString(16).toUpperCase();
                    case 0xC000: return 'RND V' + x + ', ' + nn.toString(16).toUpperCase();
                    case 0xD000: return 'DRW V' + x + ', V' + y + ', ' + n;
                    case 0xE000:
                        if (nn === 0x9E) return 'SKP V' + x;
                        if (nn === 0xA1) return 'SKNP V' + x;
                        return 'UNKNOWN';
                    case 0xF000:
                        switch (nn) {
                            case 0x07: return 'LD V' + x + ', DT';
                            case 0x0A: return 'LD V' + x + ', K';
                            case 0x15: return 'LD DT, V' + x;
                            case 0x18: return 'LD ST, V' + x;
                            case 0x1E: return 'ADD I, V' + x;
                            case 0x29: return 'LD F, V' + x;
                            case 0x33: return 'LD B, V' + x;
                            case 0x55: return 'LD [I], V' + x;
                            case 0x65: return 'LD V' + x + ', [I]';
                            default: return 'UNKNOWN';
                        }
                    default: return 'UNKNOWN';
                }
            }

            // Instruction handlers
            _0xxx(opcode) {
                switch (opcode) {
                    case 0x00E0: // CLS
                        this.display.fill(0);
                        this.updateDisplay();
                        break;
                    case 0x00EE: // RET
                        this.sp--;
                        this.pc = this.stack[this.sp];
                        break;
                    default: // SYS
                        // Not implemented in most CHIP-8 implementations
                        break;
                }
            }

            _1xxx(opcode) { // JP addr
                this.pc = opcode & 0x0FFF;
            }

            _2xxx(opcode) { // CALL addr
                this.stack[this.sp] = this.pc;
                this.sp++;
                this.pc = opcode & 0x0FFF;
            }

            _3xxx(opcode) { // SE Vx, byte
                const x = (opcode & 0x0F00) >> 8;
                const byte = opcode & 0x00FF;
                if (this.v[x] === byte) {
                    this.pc += 2;
                }
            }

            _4xxx(opcode) { // SNE Vx, byte
                const x = (opcode & 0x0F00) >> 8;
                const byte = opcode & 0x00FF;
                if (this.v[x] !== byte) {
                    this.pc += 2;
                }
            }

            _5xxx(opcode) { // SE Vx, Vy
                const x = (opcode & 0x0F00) >> 8;
                const y = (opcode & 0x00F0) >> 4;
                if (this.v[x] === this.v[y]) {
                    this.pc += 2;
                }
            }

            _6xxx(opcode) { // LD Vx, byte
                const x = (opcode & 0x0F00) >> 8;
                const byte = opcode & 0x00FF;
                this.v[x] = byte;
            }

            _7xxx(opcode) { // ADD Vx, byte
                const x = (opcode & 0x0F00) >> 8;
                const byte = opcode & 0x00FF;
                this.v[x] = (this.v[x] + byte) & 0xFF;
            }

            _8xxx(opcode) { // Various Vx, Vy operations
                const x = (opcode & 0x0F00) >> 8;
                const y = (opcode & 0x00F0) >> 4;
                const n = opcode & 0x000F;

                switch (n) {
                    case 0x0: // LD Vx, Vy
                        this.v[x] = this.v[y];
                        break;
                    case 0x1: // OR Vx, Vy
                        this.v[x] |= this.v[y];
                        break;
                    case 0x2: // AND Vx, Vy
                        this.v[x] &= this.v[y];
                        break;
                    case 0x3: // XOR Vx, Vy
                        this.v[x] ^= this.v[y];
                        break;
                    case 0x4: // ADD Vx, Vy
                        const sum = this.v[x] + this.v[y];
                        this.v[0xF] = sum > 0xFF ? 1 : 0;
                        this.v[x] = sum & 0xFF;
                        break;
                    case 0x5: // SUB Vx, Vy
                        this.v[0xF] = this.v[x] > this.v[y] ? 1 : 0;
                        this.v[x] = (this.v[x] - this.v[y] + 256) & 0xFF;
                        break;
                    case 0x6: // SHR Vx {, Vy}
                        this.v[0xF] = this.v[x] & 1;
                        this.v[x] >>= 1;
                        break;
                    case 0x7: // SUBN Vx, Vy
                        this.v[0xF] = this.v[y] > this.v[x] ? 1 : 0;
                        this.v[x] = (this.v[y] - this.v[x] + 256) & 0xFF;
                        break;
                    case 0xE: // SHL Vx {, Vy}
                        this.v[0xF] = (this.v[x] >> 7) & 1;
                        this.v[x] <<= 1;
                        this.v[x] &= 0xFF;
                        break;
                }
            }

            _9xxx(opcode) { // SNE Vx, Vy
                const x = (opcode & 0x0F00) >> 8;
                const y = (opcode & 0x00F0) >> 4;
                if (this.v[x] !== this.v[y]) {
                    this.pc += 2;
                }
            }

            _Axxx(opcode) { // LD I, addr
                this.i = opcode & 0x0FFF;
            }

            _Bxxx(opcode) { // JP V0, addr
                this.pc = (opcode & 0x0FFF) + this.v[0];
            }

            _Cxxx(opcode) { // RND Vx, byte
                const x = (opcode & 0x0F00) >> 8;
                const byte = opcode & 0x00FF;
                this.v[x] = Math.floor(Math.random() * 256) & byte;
            }

            _Dxxx(opcode) { // DRW Vx, Vy, nibble
                const x = (opcode & 0x0F00) >> 8;
                const y = (opcode & 0x00F0) >> 4;
                const height = opcode & 0x000F;

                this.v[0xF] = 0; // Clear collision flag

                for (let row = 0; row < height; row++) {
                    const spriteByte = this.memory[this.i + row];

                    for (let col = 0; col < 8; col++) {
                        if ((spriteByte & (0x80 >> col)) !== 0) {
                            const pixelX = (this.v[x] + col) % 64;
                            const pixelY = (this.v[y] + row) % 32;
                            const pixelIndex = pixelY * 64 + pixelX;

                            if (this.display[pixelIndex] === 1) {
                                this.v[0xF] = 1; // Set collision flag
                            }

                            this.display[pixelIndex] ^= 1; // XOR
                        }
                    }
                }

                this.updateDisplay();
            }

            _Exxx(opcode) { // Key operations
                const x = (opcode & 0x0F00) >> 8;
                const nn = opcode & 0x00FF;

                if (nn === 0x9E) { // SKP Vx
                    if (this.keys[this.v[x]] === 1) {
                        this.pc += 2;
                    }
                } else if (nn === 0xA1) { // SKNP Vx
                    if (this.keys[this.v[x]] === 0) {
                        this.pc += 2;
                    }
                }
            }

            _Fxxx(opcode) { // Various operations
                const x = (opcode & 0x0F00) >> 8;
                const nn = opcode & 0x00FF;

                switch (nn) {
                    case 0x07: // LD Vx, DT
                        this.v[x] = this.delayTimer;
                        break;
                    case 0x0A: // LD Vx, K
                        // Wait for key press
                        this.paused = true;
                        this.stepping = true;
                        // This will be handled in the key press event
                        break;
                    case 0x15: // LD DT, Vx
                        this.delayTimer = this.v[x];
                        break;
                    case 0x18: // LD ST, Vx
                        this.soundTimer = this.v[x];
                        break;
                    case 0x1E: // ADD I, Vx
                        const sum = this.i + this.v[x];
                        this.v[0xF] = sum > 0xFFF ? 1 : 0;
                        this.i = sum & 0xFFF;
                        break;
                    case 0x29: // LD F, Vx
                        this.i = this.v[x] * 5; // Font set is 5 bytes per digit
                        break;
                    case 0x33: // LD B, Vx
                        // Convert to BCD
                        const value = this.v[x];
                        this.memory[this.i] = Math.floor(value / 100);
                        this.memory[this.i + 1] = Math.floor((value / 10) % 10);
                        this.memory[this.i + 2] = value % 10;
                        break;
                    case 0x55: // LD [I], Vx
                        for (let i = 0; i <= x; i++) {
                            this.memory[this.i + i] = this.v[i];
                        }
                        break;
                    case 0x65: // LD Vx, [I]
                        for (let i = 0; i <= x; i++) {
                            this.v[i] = this.memory[this.i + i];
                        }
                        break;
                }
