            executeInstruction() {
                // Read 2-byte instruction
                const highByte = this.memory[this.pc];
                const lowByte = this.memory[this.pc + 1];
                this.currentInstruction = (highByte << 8) | lowByte;

                // Execute instruction
                const opcode = this.currentInstruction & 0xF000;
                if (this.instructions[opcode]) {
                    this.instructions[opcode](this.currentInstruction);
                }

                // Move to next instruction
                this.pc += 2;

                // Update debugger
                this.updateDebugger();
